<section class="card"><div class="card-heading"><div><span class="section-kicker">DIRETÓRIO CENTRAL</span><h2>Registrar usuário de um produto</h2></div><span class="badge"><?= count($users) ?> usuários</span></div><form method="post" action="/usuarios-sistemas" class="form-grid"><?= csrf_field() ?><label>Sistema <select name="system_id" required><?php foreach ($systems as $system): ?><option value="<?= e($system['id']) ?>"><?= e($system['name']) ?></option><?php endforeach; ?></select></label><label>ID externo <input name="external_id"></label><label>ID da empresa <input name="tenant_external_id"></label><label>Empresa <input name="tenant_name"></label><label>Nome <input name="name" required></label><label>E-mail <input type="email" name="email"></label><label>Papel <input name="role" placeholder="owner, admin, operator"></label><label>Status <select name="status"><option value="active">Ativo</option><option value="invited">Convidado</option><option value="suspended">Suspenso</option><option value="inactive">Inativo</option></select></label><div class="actions"><button>Salvar usuário</button></div></form></section>
<section class="card users-list"><div class="table-wrap"><table><thead><tr><th>Sistema</th><th>Empresa</th><th>Usuário</th><th>Papel</th><th>Último acesso</th><th>Status</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['system_name']) ?></td><td><?= e($user['tenant_name']) ?></td><td><strong><?= e($user['name']) ?></strong><br><span class="muted"><?= e($user['email']) ?></span></td><td><?= e($user['role']) ?></td><td><?= e($user['last_seen_at'] ?: '—') ?></td><td><form method="post" action="/usuarios-sistemas/atualizar" class="status-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($user['id']) ?>"><select name="status"><?php foreach (['active','invited','suspended','inactive'] as $value): ?><option <?= $user['status'] === $value ? 'selected' : '' ?>><?= $value ?></option><?php endforeach; ?></select><button>Alterar</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
